-- Versioned game assumptions and ownership entities; no starting career is mutated.
begin;
create table if not exists public.f1_team_game_baselines (
 id bigint generated by default as identity primary key,
 team_id bigint not null references public.f1_team_facts(id), team_slug text not null,
 season integer not null check(season>=1950), dataset_version text not null,
 basis text not null check(basis='game_assumption'), rating_scale text not null,
 dimensions jsonb not null, ratings jsonb not null, facilities jsonb not null,
 financial_assumptions_usd_millions jsonb not null, objectives jsonb not null,
 method text not null, reference_url text not null, reference_as_of date not null,
 unique(team_id,season,dataset_version)
);
create table if not exists public.f1_owners (
 id bigint generated by default as identity primary key,
 slug text not null unique, name text not null, kind text not null,
 source_url text, verified_on date, notes text
);
create table if not exists public.f1_owner_game_baselines (
 id bigint generated by default as identity primary key,
 owner_id bigint not null references public.f1_owners(id), dataset_version text not null,
 basis text not null check(basis='game_assumption'), preferences jsonb not null,
 notes text not null, unique(owner_id,dataset_version)
);
create table if not exists public.f1_team_ownership_periods (
 id bigint generated by default as identity primary key,
 team_id bigint not null references public.f1_team_facts(id),
 owner_id bigint not null references public.f1_owners(id),
 dataset_version text not null, relationship text not null,
 ownership_percentage numeric(7,4) check(ownership_percentage between 0 and 100),
 effective_from date not null, effective_until date,
 basis text not null check(basis in ('published_reference','game_assumption','career_generated')),
 source_url text, verified_on date, notes text,
 check(effective_until is null or effective_until>=effective_from),
 unique(team_id,owner_id,dataset_version,effective_from)
);
create index if not exists f1_team_ownership_periods_team_date_idx on public.f1_team_ownership_periods(team_id,effective_from,effective_until);
create index if not exists f1_team_ownership_periods_owner_idx on public.f1_team_ownership_periods(owner_id);
alter table public.f1_team_game_baselines enable row level security;
alter table public.f1_owners enable row level security;
alter table public.f1_team_ownership_periods enable row level security;
alter table public.f1_owner_game_baselines enable row level security;
drop policy if exists f1_team_baselines_public_read on public.f1_team_game_baselines;
create policy f1_team_baselines_public_read on public.f1_team_game_baselines for select to anon,authenticated using (true);
drop policy if exists f1_owners_public_read on public.f1_owners;
create policy f1_owners_public_read on public.f1_owners for select to anon,authenticated using (true);
drop policy if exists f1_ownership_public_read on public.f1_team_ownership_periods;
create policy f1_ownership_public_read on public.f1_team_ownership_periods for select to anon,authenticated using (true);
drop policy if exists f1_owner_baselines_public_read on public.f1_owner_game_baselines;
create policy f1_owner_baselines_public_read on public.f1_owner_game_baselines for select to anon,authenticated using (true);
grant select on public.f1_team_game_baselines,public.f1_owners,public.f1_team_ownership_periods,public.f1_owner_game_baselines to anon,authenticated;

