insert into public.f1_owners(slug,name,kind,source_url,verified_on)
select x->>'slug',x->>'name',x->>'kind',x->>'source_url','2026-10-27'::date from src
on conflict(slug) do nothing;

with src as (select jsonb_array_elements($owner_profiles$[{"slug":"mumtalakat","preferences":{"patience":78,"sporting_ambition":75,"financial_support":82,"risk_tolerance":50,"commercial_focus":84,"youth_preference":60}},{"slug":"cyvn","preferences":{"patience":78,"sporting_ambition":75,"financial_support":82,"risk_tolerance":50,"commercial_focus":84,"youth_preference":60}},{"slug":"mercedes-benz","preferences":{"patience":76,"sporting_ambition":90,"financial_support":88,"risk_tolerance":60,"commercial_focus":85,"youth_preference":72}},{"slug":"ineos","preferences":{"patience":68,"sporting_ambition":84,"financial_support":82,"risk_tolerance":70,"commercial_focus":91,"youth_preference":81}},{"slug":"motorsport-invest","preferences":{"patience":72,"sporting_ambition":79,"financial_support":78,"risk_tolerance":59,"commercial_focus":82,"youth_preference":66}},{"slug":"ferrari","preferences":{"patience":76,"sporting_ambition":90,"financial_support":88,"risk_tolerance":60,"commercial_focus":85,"youth_preference":72}},{"slug":"red-bull","preferences":{"patience":68,"sporting_ambition":84,"financial_support":82,"risk_tolerance":70,"commercial_focus":91,"youth_preference":81}},{"slug":"dorilton","preferences":{"patience":72,"sporting_ambition":79,"financial_support":78,"risk_tolerance":59,"commercial_focus":82,"youth_preference":66}},{"slug":"aston-consortium","preferences":{"patience":68,"sporting_ambition":89,"financial_support":83,"risk_tolerance":65,"commercial_focus":82,"youth_preference":65}},{"slug":"gene-haas","preferences":{"patience":69,"sporting_ambition":77,"financial_support":70,"risk_tolerance":57,"commercial_focus":73,"youth_preference":70}},{"slug":"audi","preferences":{"patience":76,"sporting_ambition":90,"financial_support":88,"risk_tolerance":60,"commercial_focus":85,"youth_preference":72}},{"slug":"qia","preferences":{"patience":78,"sporting_ambition":75,"financial_support":82,"risk_tolerance":50,"commercial_focus":84,"youth_preference":60}},{"slug":"renault","preferences":{"patience":76,"sporting_ambition":90,"financial_support":88,"risk_tolerance":60,"commercial_focus":85,"youth_preference":72}},{"slug":"otro","preferences":{"patience":78,"sporting_ambition":75,"financial_support":82,"risk_tolerance":50,"commercial_focus":84,"youth_preference":60}},{"slug":"twg","preferences":{"patience":68,"sporting_ambition":84,"financial_support":82,"risk_tolerance":70,"commercial_focus":91,"youth_preference":81}},{"slug":"gm","preferences":{"patience":76,"sporting_ambition":90,"financial_support":88,"risk_tolerance":60,"commercial_focus":85,"youth_preference":72}}]$owner_profiles$::jsonb) as x)
insert into public.f1_owner_game_baselines(owner_id,dataset_version,basis,preferences,notes)
select o.id,'f1-team-baseline-2027-v1','game_assumption',x->'preferences','Starting gameplay assumption by ownership type; not a claim about actual owner finances or intentions.'
from src join public.f1_owners o on o.slug=x->>'slug'
on conflict(owner_id,dataset_version) do nothing;

with src as (select jsonb_array_elements($links$[{"team_slug":"mclaren","owner_slug":"mumtalakat","relationship":"majority_investor","percentage":null},{"team_slug":"mclaren","owner_slug":"cyvn","relationship":"minority_investor","percentage":null},{"team_slug":"mercedes","owner_slug":"mercedes-benz","relationship":"shareholder","percentage":null},{"team_slug":"mercedes","owner_slug":"ineos","relationship":"shareholder","percentage":null},{"team_slug":"mercedes","owner_slug":"motorsport-invest","relationship":"shareholder","percentage":null},{"team_slug":"ferrari","owner_slug":"ferrari","relationship":"parent","percentage":null},{"team_slug":"red-bull-racing","owner_slug":"red-bull","relationship":"parent","percentage":null},{"team_slug":"racing-bulls","owner_slug":"red-bull","relationship":"parent","percentage":null},{"team_slug":"williams","owner_slug":"dorilton","relationship":"owner","percentage":null},{"team_slug":"aston-martin","owner_slug":"aston-consortium","relationship":"controlling_group","percentage":null},{"team_slug":"haas","owner_slug":"gene-haas","relationship":"owner","percentage":null},{"team_slug":"audi","owner_slug":"audi","relationship":"majority_investor","percentage":null},{"team_slug":"audi","owner_slug":"qia","relationship":"minority_investor","percentage":null},{"team_slug":"alpine","owner_slug":"renault","relationship":"majority_investor","percentage":76},{"team_slug":"alpine","owner_slug":"otro","relationship":"minority_investor","percentage":24},{"team_slug":"cadillac","owner_slug":"twg","relationship":"backer","percentage":null},{"team_slug":"cadillac","owner_slug":"gm","relationship":"backer","percentage":null}]$links$::jsonb) as x)
insert into public.f1_team_ownership_periods(team_id,owner_id,dataset_version,relationship,ownership_percentage,effective_from,basis,source_url,verified_on,notes)
select t.id,o.id,'f1-team-baseline-2027-v1',x->>'relationship',(x->>'percentage')::numeric,'2027-01-01'::date,'game_assumption',o.source_url,'2026-10-27'::date,'2027 continuity is a game projection; stake not stated where unknown.'
from src join public.f1_team_facts t on t.slug=src.x->>'team_slug' join public.f1_owners o on o.slug=src.x->>'owner_slug'
on conflict(team_id,owner_id,dataset_version,effective_from) do nothing;

do $$ begin
 if (select count(*) from public.f1_team_game_baselines where dataset_version='f1-team-baseline-2027-v1')<>11 then raise exception 'Expected 11 team baselines; transaction cancelled'; end if;
 if (select count(*) from public.f1_owner_game_baselines where dataset_version='f1-team-baseline-2027-v1')<>16 then raise exception 'Expected 16 owner profiles; transaction cancelled'; end if;
 if (select count(*) from public.f1_team_ownership_periods where dataset_version='f1-team-baseline-2027-v1')<>17 then raise exception 'Expected 17 ownership links; transaction cancelled'; end if;
end $$;
commit;
